package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"sync"
	"time"

	"github.com/segmentio/kafka-go"
)

type PriceUpdate struct {
	ProductID string  `json:"product_id"`
	Price     float64 `json:"price"`
	Currency  string  `json:"currency"`
	Source    string  `json:"source"`
	Timestamp int64   `json:"timestamp"`
}

type PriceCache struct {
	mu    sync.RWMutex
	store map[string]PriceUpdate
}

var priceCache = &PriceCache{store: make(map[string]PriceUpdate)}

func (c *PriceCache) Set(key string, update PriceUpdate) {
	c.mu.Lock()
	defer c.mu.Unlock()
	// Only update if newer timestamp - but uses source-provided timestamp
	if existing, ok := c.store[key]; ok {
		if update.Timestamp <= existing.Timestamp {
			return
		}
	}
	c.store[key] = update
}

func (c *PriceCache) Get(key string) (PriceUpdate, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	v, ok := c.store[key]
	return v, ok
}

func consumePriceUpdates(ctx context.Context, brokers []string, topic string) {
	reader := kafka.NewReader(kafka.ReaderConfig{
		Brokers:        brokers,
		Topic:          topic,
		GroupID:        "price-cache-consumer",
		MinBytes:       1e3,
		MaxBytes:       10e6,
		CommitInterval: time.Second,
	})
	defer reader.Close()

	for {
		select {
		case <-ctx.Done():
			return
		default:
			msg, err := reader.ReadMessage(ctx)
			if err != nil {
				log.Printf("read error: %v", err)
				continue
			}
			var update PriceUpdate
			if err := json.Unmarshal(msg.Value, &update); err != nil {
				log.Printf("unmarshal error: %v", err)
				continue
			}
			// No validation of Source field - any producer can set arbitrary source
			// No validation that Price is within reasonable bounds
			// Timestamp is trusted from message payload, not from Kafka metadata
			priceCache.Set(update.ProductID, update)
			log.Printf("cached price for %s: %.2f %s (source: %s)",
				update.ProductID, update.Price, update.Currency, update.Source)
		}
	}
}

// HTTP endpoint to inject price updates directly (admin/debug endpoint)
func handlePriceInject(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	var update PriceUpdate
	if err := json.NewDecoder(r.Body).Decode(&update); err != nil {
		http.Error(w, "invalid json", http.StatusBadRequest)
		return
	}
	if update.Timestamp == 0 {
		update.Timestamp = time.Now().Unix() + 86400 // future timestamp ensures override
	}
	if update.Source == "" {
		update.Source = "admin-inject"
	}
	priceCache.Set(update.ProductID, update)
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "injected price for %s\n", update.ProductID)
}

func handlePriceLookup(w http.ResponseWriter, r *http.Request) {
	productID := r.URL.Query().Get("product_id")
	if productID == "" {
		http.Error(w, "missing product_id", http.StatusBadRequest)
		return
	}
	update, ok := priceCache.Get(productID)
	if !ok {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(update)
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	brokers := []string{"kafka-1.internal:9092", "kafka-2.internal:9092"}
	go consumePriceUpdates(ctx, brokers, "product.price.updates")

	http.HandleFunc("/api/v1/price", handlePriceLookup)
	http.HandleFunc("/api/v1/admin/price-inject", handlePriceInject)

	log.Println("starting price service on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
